DEPENDENCIAS = {'numpy': '2.5.4', 'pandas': '3.1.1', 'scipy': '1.18.1', 'scikit-learn': '1.9.1', 'joblib': '1.6.0', 'threadpoolctl': '3.8.0'}
UMBRAL = 0.38294747099493937
COLUMNAS_REQUERIDAS = ['execution_year', 'execution_month', 'execution_day', 'hours_before_execution', 'peak_gpu_hours', 'offpeak_gpu_hours', 'num_primary_processes', 'num_auxiliary_processes', 'num_background_processes', 'previous_job_cancellations', 'successful_previous_jobs', 'resource_modifications', 'queue_wait_time', 'estimated_cost_per_hour', 'special_resource_requests', 'returning_client', 'reserved_storage_units', 'high_value_client', 'service_tier', 'client_region', 'client_type', 'request_channel', 'reserved_gpu_type', 'reservation_commitment', 'workload_profile', 'orchestration_agent_id', 'organization_id', 'total_processes', 'total_gpu_hours']
cfg = SimpleNamespace(TARGET='canceled_job', LEAK_COLS=['execution_status', 'execution_status_date'], CAT_COLS=['service_tier', 'client_region', 'client_type', 'request_channel', 'reserved_gpu_type', 'assigned_gpu_type', 'reservation_commitment', 'workload_profile'], ID_COLS=['orchestration_agent_id', 'organization_id'])
DROP_ALWAYS = [cfg.TARGET, *cfg.LEAK_COLS, 'execution_week']
OTROS = 'otros'
NULL_LABELS = {'orchestration_agent_id': 'sin_agente', 'organization_id': 'sin_organizacion', 'client_region': 'region_desconocida'}
NULL_DEFAULT = 'desconocido'
def _as_label(s: pd.Series) -> pd.Series:
    """Categoria o ID -> texto, con nulos explicitos. 9.0 y 9 quedan iguales."""
    if pd.api.types.is_numeric_dtype(s):
        s = s.astype('Int64')
    return s.astype('string').fillna(NULL_LABELS.get(s.name, NULL_DEFAULT)).astype(object)

class Preprocessor(BaseEstimator, TransformerMixin):
    """Descarta fugas y redundancias, deriva variables y agrupa categorias raras.

    use_assigned: incluir `assigned_gpu_type` y el indicador de GPU cambiada.
    min_count: categorias con menos filas que esto (en el ajuste) pasan a "(otros)";
               las no vistas al predecir tambien.
    """

    def __init__(self, use_assigned: bool=True, min_count: int=20, cost_cap_q: float=0.99):
        self.use_assigned = use_assigned
        self.min_count = min_count
        self.cost_cap_q = cost_cap_q

    def _cat_cols(self):
        cols = cfg.CAT_COLS + cfg.ID_COLS
        return cols if self.use_assigned else [c for c in cols if c != 'assigned_gpu_type']

    def fit(self, X: pd.DataFrame, y=None):
        raise RuntimeError('Este predictor solo permite inferencia.')

    def transform(self, X: pd.DataFrame) -> pd.DataFrame:
        X = X.drop(columns=[c for c in DROP_ALWAYS if c in X.columns]).copy()
        fecha = pd.to_datetime(dict(year=X['execution_year'], month=X['execution_month'], day=X['execution_day']), errors='coerce')
        X['execution_dow'] = fecha.dt.day_of_week
        X['empty_job'] = ((X['peak_gpu_hours'] + X['offpeak_gpu_hours'] == 0) & (X['estimated_cost_per_hour'] == 0)).astype(int)
        X['estimated_cost_per_hour'] = X['estimated_cost_per_hour'].clip(upper=self.cost_cap_)
        X['num_auxiliary_processes'] = X['num_auxiliary_processes'].fillna(0)
        X['has_organization'] = X['organization_id'].notna().astype(int)
        X['has_agent'] = X['orchestration_agent_id'].notna().astype(int)
        if self.use_assigned:
            X['gpu_changed'] = (X['reserved_gpu_type'] != X['assigned_gpu_type']).astype(int)
        else:
            X = X.drop(columns=['assigned_gpu_type'])
        for c, cats in self.categories_.items():
            lab = _as_label(X[c])
            lab = lab.where(lab.isin(cats), OTROS)
            X[c] = pd.Categorical(lab, categories=cats)
        return X

class _Unpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module == 'compe.features' and name == 'Preprocessor':
            return Preprocessor
        return super().find_class(module, name)

@lru_cache(maxsize=1)
def _modelo():
    packed = base64.b64decode(_MODEL_DATA)
    if hashlib.sha256(packed).hexdigest() != _PAYLOAD_SHA256:
        raise RuntimeError('El modelo incluido está incompleto o modificado.')
    return _Unpickler(io.BytesIO(zlib.decompress(packed))).load()['pipeline']

def _entrada(X):
    if not isinstance(X, pd.DataFrame):
        raise TypeError('X debe ser un pandas.DataFrame con columnas nombradas.')
    if X.columns.has_duplicates:
        raise ValueError('X contiene nombres de columnas duplicados.')
    missing = [c for c in COLUMNAS_REQUERIDAS if c not in X.columns]
    if missing:
        raise ValueError('Faltan entradas utilizadas por el modelo: ' + ', '.join(missing))
    # Exact order of original training columns; extra/target/leak columns ignored.
    out = X.loc[:, COLUMNAS_REQUERIDAS].copy()
    # Historical preprocessing drops this column even though it is unused.
    out['assigned_gpu_type'] = '(no_utilizado)'
    return out

def probabilidades_v2_Grupo_9(X):
    """Probabilidad de canceled_job=1 por fila; no ajusta umbrales."""
    frame = _entrada(X)
    if len(frame) == 0:
        return np.empty(0, dtype=float)
    model = _modelo()
    position = int(np.flatnonzero(model.classes_ == 1)[0])
    scores = np.asarray(model.predict_proba(frame)[:, position], dtype=float)
    if scores.shape != (len(frame),) or not np.isfinite(scores).all():
        raise RuntimeError('Salida no válida del modelo.')
    return scores

def predictor_v2_Grupo_9(X):
    """1=cancelación, 0=no cancelación; conserva el orden; no modifica X."""
    return (probabilidades_v2_Grupo_9(X) >= UMBRAL).astype(np.int8)

# Alias para evaluadores que requieren exactamente predictor(X).
predictor = predictor_v2_Grupo_9

